def activity(activity_id, module_id, activity_type, title, content="", config=None, order=1, points=None, manual=None):
    ACTIVITIES.append((activity_id, COURSE_ID, module_id, activity_type, title, content, json.dumps(config or {}, ensure_ascii=False), order, "active", "{}", points, manual))

def sql_config(instructions, query, rows):
    return {"instructions": instructions, "databaseSchemaId": SCHEMA_ID, "defaultQuery": query, "validation": {"expectedRows": rows}}

activity("itba_a0101", "itba_m01_role", "html_content", "IT BA как связующее звено", """
<h2>IT Business Analyst: что он делает</h2>
<p>IT BA переводит бизнес-потребность в проверяемое изменение системы. Его результат — согласованное понимание: <b>какая проблема</b> решается, <b>для кого</b>, <b>каким поведением системы</b> и <b>как подтвердить</b>, что решение работает.</p>
<h3>Опорная цепочка</h3><ol><li><b>Need</b>: боль, возможность или обязательство.</li><li><b>Stakeholders</b>: пользователи, owners, support, compliance и команды интеграций.</li><li><b>Value</b>: эффект или снижение риска.</li><li><b>Solution scope</b>: изменения процесса, UI, данных и интеграций.</li><li><b>Evidence</b>: acceptance criteria, тестовые данные и метрики.</li></ol>
<p>Базовые артефакты: stakeholder map, user story/use case, business rules, AC, data dictionary, API request/response examples, SQL-проверки и traceability.</p>
<blockquote>До описания endpoint или поля сформулируйте бизнес-решение, которое оно поддерживает.</blockquote>
<p>Источник для дальнейшего чтения: <a href="https://www.iiba.org/career-resources/a-business-analysis-professionals-foundation-for-success/babok/">IIBA — BABOK Guide overview</a>.</p>""", order=1)
