def seed(db_path: Path = DB_PATH) -> None:
    conn = sqlite3.connect(db_path)
    try:
        required = {"courses", "modules", "activities", "sqlSchemas"}
        actual = {row[0] for row in conn.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        missing = required - actual
        if missing:
            raise RuntimeError(f"Database is not initialized. Missing tables: {', '.join(sorted(missing))}. Run python app.py once, then rerun this seed.")
        conn.execute("INSERT OR REPLACE INTO sqlSchemas(schemaId,title,description,initSql,status) VALUES(?,?,?,?,?)", (SCHEMA_ID, "Training bank: clients, cards, tariffs and restrictions", "SQL dataset for IT BA exercises; learners execute SELECT queries only.", SQL_SCHEMA, "active"))
        conn.execute("INSERT OR REPLACE INTO courses(courseId,title,description,category,level,displayOrder,passingScore,status) VALUES(?,?,?,?,?,?,?,?)", COURSE)
        conn.executemany("INSERT OR REPLACE INTO modules(moduleId,courseId,title,description,displayOrder,status,moduleType,maxAttempts,passingScore,reviewMode,lockAfterSubmit,isTimed,timeLimitMinutes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)", MODULES)
        conn.executemany("INSERT OR REPLACE INTO activities(activityId,courseId,moduleId,activityType,title,content,configJson,displayOrder,status,validationJson,points,manualReviewRequired) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)", ACTIVITIES)
        conn.commit()
    finally:
        conn.close()
    print(f"Seeded course {COURSE_ID}: {len(MODULES)} modules, {len(ACTIVITIES)} activities, assessment time limit 180 minutes.")

if __name__ == "__main__":
    seed()
